header_trial_patch:
diff --git a/src/proxy/hyper/request.rs b/src/proxy/hyper/request.rs
index 2e1e490..7b4e409 100644
--- a/src/proxy/hyper/request.rs
+++ b/src/proxy/hyper/request.rs
@@ -795,6 +795,13 @@ pub(super) fn strip_hop_headers(headers: &mut http::HeaderMap) {
         headers.remove(name);
     }
     for name in &HOP_HEADERS {
+        // These two custom names require SipHash on every lookup. Usually absent,
+        // they are cheaper to reject by inspecting the small parsed header list.
+        if matches!(name.as_str(), "proxy-connection" | "keep-alive")
+            && !headers.keys().any(|key| key == name)
+        {
+            continue;
+        }
         headers.remove(name);
     }
 }
